import { useState } from "react";
import { Box, Flex, Grid, Image, Text } from "@chakra-ui/react";
import { TEAM_BY_V5, fixNames, n1, ordinal, pct0, shortOf, signed1 } from "./spotlightModel";

// ─────────────────────────────────────────────────────────────────────────────
// The ten Team Spotlight charts (FRONTEND_CHART_SPEC, 2026-10-21). Each takes
// the chart object straight off the file plus the team palette, and reads bare:
// labels and values on the chart, no legends beyond the one key a chart needs.
// SVG for the lines (viewBox, so they stretch to the card); HTML everywhere
// else. Sizes in rem so the same chart works on the phone.
// ─────────────────────────────────────────────────────────────────────────────

const MUTED = "rgba(255,255,255,0.55)";
const FAINT = "rgba(255,255,255,0.35)";
const LINE = "rgba(255,255,255,0.08)";
const RED = "#E53E3E";
const ORANGE = "#CC5500";
const GREY = "#52525B";

const Small = ({ children, ...rest }) => (
  <Text fontSize="0.68rem" fontWeight="900" color={MUTED} textTransform="uppercase" letterSpacing="0.08em" {...rest}>{children}</Text>
);

// ── 1 · The climb: rating rank week by week, rank 1 at the top ───────────────
export const ClimbChart = ({ chart, palette, ranked = 18 }) => {
  const pts = chart.data ?? [];
  const W = 640, H = 260, L = 44, R = 30, T = 24, B = 34;
  const x = (i) => L + (i / Math.max(1, pts.length - 1)) * (W - L - R);
  const y = (rank) => T + ((rank - 1) / (ranked - 1)) * (H - T - B);
  const path = pts.map((p, i) => `${i ? "L" : "M"} ${x(i)} ${y(p.rank)}`).join(" ");
  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: "block", overflow: "visible" }}>
      {[1, 6, 12, 18].map((r) => (
        <g key={r}>
          <line x1={L} x2={W - R} y1={y(r)} y2={y(r)} stroke={LINE} />
          <text x={L - 10} y={y(r) + 4} textAnchor="end" fontSize="12" fontWeight="800" fill={FAINT}>{ordinal(r)}</text>
        </g>
      ))}
      <path d={path} fill="none" stroke={palette.ink} strokeWidth="4" strokeLinejoin="round" strokeLinecap="round" />
      {pts.map((p, i) => {
        const last = i === pts.length - 1;
        const changed = i === 0 || p.rank !== pts[i - 1].rank;
        return (
          <g key={i}>
            <circle cx={x(i)} cy={y(p.rank)} r={last ? 9 : 5.5} fill={last ? palette.ink : "#141416"} stroke={palette.ink} strokeWidth="3" />
            {(changed || last) && (
              <text x={x(i)} y={y(p.rank) - 14} textAnchor="middle" fontSize={last ? 20 : 14} fontWeight="900" fill={last ? "#FFFFFF" : "rgba(255,255,255,0.75)"}>{ordinal(p.rank)}</text>
            )}
            <text x={x(i)} y={H - 8} textAnchor="middle" fontSize="12" fontWeight="800" fill={FAINT}>{p.week === "pre" ? "PRE" : `WK ${p.week}`}</text>
          </g>
        );
      })}
    </svg>
  );
};

// ── 2 · Win probability, one small panel per game ────────────────────────────
const WP_W = 220, WP_H = 110;
const WpPanel = ({ panel, palette, id }) => {
  const s = panel.series ?? [];
  const x = (i) => (i / Math.max(1, s.length - 1)) * WP_W;
  const y = (wp) => WP_H - wp * WP_H;
  const line = s.map((p, i) => `${i ? "L" : "M"} ${x(i)} ${y(p.wp)}`).join(" ");
  const area = `${line} L ${WP_W} ${WP_H / 2} L 0 ${WP_H / 2} Z`;
  const peak = s.reduce((m, p) => Math.max(m, p.wp), 0);
  const low = s.reduce((m, p) => Math.min(m, p.wp), 1);
  const won = String(panel.label).startsWith("W");
  return (
    <Box minW={0} bg="rgba(255,255,255,0.03)" borderRadius="md" p="0.6rem">
      <Flex justify="space-between" align="baseline" mb="0.35rem" gap="0.4rem">
        <Text fontSize="0.82rem" fontWeight="900" color={won ? "white" : MUTED} textTransform="uppercase" lineClamp={1}>{fixNames(panel.label)}</Text>
      </Flex>
      <svg viewBox={`0 0 ${WP_W} ${WP_H}`} width="100%" preserveAspectRatio="none" style={{ display: "block", height: "5.5rem" }}>
        <defs>
          <clipPath id={`wp-up-${id}`}><rect x="0" y="0" width={WP_W} height={WP_H / 2} /></clipPath>
        </defs>
        <path d={area} fill={palette.ink} fillOpacity="0.55" clipPath={`url(#wp-up-${id})`} />
        <line x1="0" x2={WP_W} y1={WP_H / 2} y2={WP_H / 2} stroke="rgba(255,255,255,0.35)" strokeDasharray="4 4" vectorEffect="non-scaling-stroke" />
        <path d={line} fill="none" stroke="#FFFFFF" strokeWidth="1.6" vectorEffect="non-scaling-stroke" />
      </svg>
      <Flex justify="space-between" mt="0.3rem">
        <Small fontSize="0.62rem">High {pct0(peak * 100)}</Small>
        <Small fontSize="0.62rem">Low {pct0(low * 100)}</Small>
      </Flex>
    </Box>
  );
};
export const WinProbChart = ({ chart, palette, mobile }) => (
  <Grid templateColumns={mobile ? "repeat(2, minmax(0,1fr))" : `repeat(${(chart.panels ?? []).length || 1}, minmax(0,1fr))`} gap="0.6rem">
    {(chart.panels ?? []).map((p, i) => <WpPanel key={i} id={i} panel={p} palette={palette} />)}
  </Grid>
);

// ── 3 · Fingerprint: every ranked metric as a bar from the 50th percentile ───
const SIDE_LABEL = { offense: "Offense", defense: "Defense", game: "Game" };
const FingerRow = ({ d, palette }) => {
  const off = d.percentile - 50;
  return (
    <Grid templateColumns="minmax(0,1.3fr) minmax(0,1fr) 3.8rem" columnGap="0.6rem" alignItems="center" py="0.22rem" borderBottom={`1px solid ${LINE}`}>
      <Text fontSize="0.78rem" fontWeight="700" color="rgba(255,255,255,0.85)" lineClamp={1} title={d.label}>{d.label}</Text>
      <Box position="relative" h="0.7rem">
        <Box position="absolute" left="50%" top="-0.15rem" bottom="-0.15rem" w="1px" bg="rgba(255,255,255,0.3)" />
        <Box position="absolute" top={0} bottom={0} borderRadius="2px" bg={off >= 0 ? palette.ink : RED} opacity={off >= 0 ? 1 : 0.8}
          style={off >= 0 ? { left: "50%", width: `${off}%` } : { right: "50%", width: `${-off}%` }} />
      </Box>
      <Flex direction="column" align="flex-end" lineHeight={1.05}>
        <Text fontSize="0.78rem" fontWeight="900" color="white" fontVariantNumeric="tabular-nums">{d.display}</Text>
        <Text fontSize="0.6rem" fontWeight="800" color={FAINT}>{d.rank} of {d.of}</Text>
      </Flex>
    </Grid>
  );
};
export const FingerprintChart = ({ chart, palette, mobile }) => {
  const sides = ["offense", "defense", "game"];
  return (
    <Grid templateColumns={mobile ? "minmax(0,1fr)" : "repeat(3, minmax(0,1fr))"} gap={mobile ? "1rem" : "1.5rem"}>
      {sides.map((side) => (
        <Box key={side} minW={0}>
          <Small color={palette.ink} mb="0.4rem">{SIDE_LABEL[side]}</Small>
          {(chart.data ?? []).filter((d) => d.side === side).sort((a, b) => b.percentile - a.percentile).map((d) => <FingerRow key={d.label} d={d} palette={palette} />)}
        </Box>
      ))}
    </Grid>
  );
};

// ── 4 · Every possession: the drives, in order, game by game ─────────────────
const driveInk = (result, palette) => ({
  TD: palette.ink, FG: palette.soft, Punt: GREY, INT: RED, FUMB: RED, Downs: ORANGE, MissedFG: ORANGE,
}[result] ?? "rgba(255,255,255,0.18)");
const Strip = ({ drives, palette, dim }) => (
  <Flex gap="2px" h="1.15rem">
    {drives.map((d, i) => (
      <Box key={i} flex={1} minW="0.35rem" bg={driveInk(d.result, palette)} opacity={dim ? 0.55 : 1} borderRadius="2px"
        title={`${d.result} · Q${d.quarter} · own ${d.start} · ${d.plays} plays`} />
    ))}
  </Flex>
);
export const PossessionsChart = ({ chart, palette, teamId, mobile }) => {
  const rows = chart.rows ?? [];
  const keyItems = [["TD", palette.ink], ["FG", palette.soft], ["Punt", GREY], ["Turnover", RED], ["Downs / missed FG", ORANGE]];
  return (
    <Box>
      <Flex gap="0.9rem" wrap="wrap" mb="0.75rem">
        {keyItems.map(([label, ink]) => (
          <Flex key={label} align="center" gap="0.35rem"><Box w="0.7rem" h="0.7rem" borderRadius="2px" bg={ink} /><Small>{label}</Small></Flex>
        ))}
      </Flex>
      <Flex direction="column" gap="0.75rem">
        {rows.map((r) => (
          <Grid key={r.label} templateColumns={mobile ? "minmax(0,1fr)" : "8.5rem minmax(0,1fr)"} columnGap="0.9rem" rowGap="0.3rem" alignItems="center">
            <Text fontSize="0.85rem" fontWeight="900" color="white" textTransform="uppercase">{fixNames(r.label)}</Text>
            <Flex direction="column" gap="3px" minW={0}>
              <Flex align="center" gap="0.5rem"><Small w="3rem" flexShrink={0} color={palette.ink}>{shortOf(teamId)}</Small><Box flex={1} minW={0}><Strip drives={r.offense ?? []} palette={palette} /></Box></Flex>
              <Flex align="center" gap="0.5rem"><Small w="3rem" flexShrink={0}>Opp</Small><Box flex={1} minW={0}><Strip drives={r.defense ?? r.opponent ?? []} palette={palette} dim /></Box></Flex>
            </Flex>
          </Grid>
        ))}
      </Flex>
    </Box>
  );
};

// ── 5 · Quarter by quarter: points scored minus allowed ──────────────────────
const cellBg = (diff, palette) => {
  if (diff === 0) return "rgba(255,255,255,0.05)";
  const a = Math.min(1, Math.abs(diff) / 21) * 0.85 + 0.15;
  return diff > 0 ? `${palette.ink}${Math.round(a * 255).toString(16).padStart(2, "0")}` : `rgba(229,62,62,${a})`;
};
export const QuartersChart = ({ chart, palette }) => {
  const cols = chart.columns ?? ["Q1", "Q2", "Q3", "Q4"];
  const grid = `minmax(5.5rem,1.2fr) repeat(${cols.length}, minmax(0,1fr))`;
  const Cell = ({ us, them, bold }) => (
    <Flex direction="column" align="center" justify="center" py="0.45rem" borderRadius="4px" bg={cellBg(us - them, palette)}>
      <Text fontSize={bold ? "1.15rem" : "1rem"} fontWeight="950" color="white" lineHeight={1}>{signed1(us - them).replace(".0", "")}</Text>
      <Text fontSize="0.62rem" fontWeight="800" color="rgba(255,255,255,0.7)" mt="0.15rem">{us}-{them}</Text>
    </Flex>
  );
  return (
    <Box>
      <Grid templateColumns={grid} gap="4px" mb="4px">
        <Box />
        {cols.map((c) => <Small key={c} textAlign="center">{c}</Small>)}
      </Grid>
      <Flex direction="column" gap="4px">
        {(chart.rows ?? []).map((r) => (
          <Grid key={r.label} templateColumns={grid} gap="4px" alignItems="center">
            <Text fontSize="0.82rem" fontWeight="900" color="white" textTransform="uppercase" lineClamp={1}>{fixNames(r.label)}</Text>
            {cols.map((_, q) => <Cell key={q} us={r.team[q]} them={r.opponent[q]} />)}
          </Grid>
        ))}
        {chart.totals && (
          <Grid templateColumns={grid} gap="4px" alignItems="center" pt="4px" borderTop="1px solid rgba(255,255,255,0.15)">
            <Text fontSize="0.82rem" fontWeight="950" color={palette.ink} textTransform="uppercase">Total</Text>
            {cols.map((_, q) => <Cell key={q} us={chart.totals.team[q]} them={chart.totals.opponent[q]} bold />)}
          </Grid>
        )}
      </Flex>
    </Box>
  );
};

// ── 6 · The plays that swung it ──────────────────────────────────────────────
export const SwingsChart = ({ chart, palette }) => {
  const rows = chart.data ?? [];
  const max = Math.max(...rows.map((r) => Math.abs(r.swing)), 0.01);
  return (
    <Flex direction="column" gap="0.55rem">
      {rows.map((r, i) => (
        <Box key={i}>
          <Flex align="center" gap="0.6rem">
            <Text w="2.6rem" flexShrink={0} fontSize="1.05rem" fontWeight="950" color={r.swing >= 0 ? palette.ink : RED} fontVariantNumeric="tabular-nums">
              {r.swing >= 0 ? "+" : "−"}{Math.round(Math.abs(r.swing) * 100)}
            </Text>
            <Box flex={1} h="0.55rem" bg="rgba(255,255,255,0.05)" borderRadius="2px" overflow="hidden">
              <Box h="100%" bg={r.swing >= 0 ? palette.ink : RED} style={{ width: `${(Math.abs(r.swing) / max) * 100}%` }} />
            </Box>
          </Flex>
          <Text fontSize="0.78rem" fontWeight="700" color="rgba(255,255,255,0.85)" mt="0.15rem" lineClamp={1}>{r.description}</Text>
          <Small fontSize="0.6rem">{fixNames(r.game)} · Q{r.quarter} {r.clock}</Small>
        </Box>
      ))}
    </Flex>
  );
};

// ── 7 · Field position: our average drive start vs theirs, game by game ─────
export const FieldPositionChart = ({ chart, palette, teamId }) => {
  const rows = chart.data ?? [];
  const vals = rows.flatMap((r) => [r.team_start, r.opponent_start]);
  const lo = Math.floor(Math.min(...vals) / 5) * 5 - 5;
  const hi = Math.ceil(Math.max(...vals) / 5) * 5 + 5;
  const at = (v) => `${((v - lo) / (hi - lo)) * 100}%`;
  return (
    <Box>
      <Flex gap="1rem" mb="0.6rem">
        <Flex align="center" gap="0.35rem"><Box w="0.7rem" h="0.7rem" borderRadius="full" bg={palette.ink} /><Small>{shortOf(teamId)}</Small></Flex>
        <Flex align="center" gap="0.35rem"><Box w="0.7rem" h="0.7rem" borderRadius="full" bg={GREY} /><Small>Opponent</Small></Flex>
      </Flex>
      <Flex direction="column" gap="0.55rem">
        {rows.map((r) => {
          const better = r.team_start >= r.opponent_start;
          return (
            <Grid key={r.label} templateColumns="6.5rem minmax(0,1fr) 3rem" columnGap="0.6rem" alignItems="center">
              <Text fontSize="0.82rem" fontWeight="900" color="white" textTransform="uppercase" lineClamp={1}>{fixNames(r.label)}</Text>
              <Box position="relative" h="1.4rem">
                <Box position="absolute" top="50%" h="3px" mt="-1.5px" bg={better ? palette.ink : RED} opacity={0.6}
                  style={{ left: at(Math.min(r.team_start, r.opponent_start)), width: `calc(${at(Math.max(r.team_start, r.opponent_start))} - ${at(Math.min(r.team_start, r.opponent_start))})` }} />
                <Box position="absolute" top="50%" w="0.85rem" h="0.85rem" borderRadius="full" bg={GREY} style={{ left: at(r.opponent_start), transform: "translate(-50%,-50%)" }} />
                <Box position="absolute" top="50%" w="0.85rem" h="0.85rem" borderRadius="full" bg={palette.ink} style={{ left: at(r.team_start), transform: "translate(-50%,-50%)" }} />
              </Box>
              <Text fontSize="0.82rem" fontWeight="900" color={better ? "white" : RED} textAlign="right" fontVariantNumeric="tabular-nums">{signed1(r.team_start - r.opponent_start)}</Text>
            </Grid>
          );
        })}
      </Flex>
      <Flex justify="space-between" mt="0.4rem" pl="7.1rem" pr="3.6rem">
        <Small fontSize="0.6rem">Own {lo}</Small>
        <Small fontSize="0.6rem">Own {hi}</Small>
      </Flex>
    </Box>
  );
};

// ── 8 · Who carries it: season PAR, faces, "via" tags ────────────────────────
const Face = ({ src, logo }) => {
  const [bad, setBad] = useState(false);
  return (
    <Box w="2.6rem" h="2.6rem" borderRadius="0.5rem" overflow="hidden" bg="rgba(255,255,255,0.06)" flexShrink={0} display="flex" alignItems="center" justifyContent="center">
      {src && !bad
        ? <Image src={src} alt="" w="100%" h="100%" objectFit="cover" objectPosition="top" onError={() => setBad(true)} />
        : logo ? <Image src={logo} alt="" w="70%" h="70%" objectFit="contain" /> : null}
    </Box>
  );
};
export const CarriesChart = ({ chart, palette }) => {
  const rows = [...(chart.data ?? [])].sort((a, b) => b.par - a.par);
  const max = Math.max(...rows.map((r) => r.par), 1);
  return (
    <Flex direction="column" gap="0.5rem">
      {rows.map((r) => {
        const last = String(r.name).split(" ").filter((w) => !/^(jr\.?|sr\.?|ii|iii|iv|v)$/i.test(w)).slice(-1)[0];
        return (
          <Flex key={r.name} align="center" gap="0.6rem">
            <Face src={r.image_url} logo={palette.team?.logo} />
            <Box flex={1} minW={0}>
              <Flex align="baseline" gap="0.4rem" minW={0}>
                <Text fontSize="0.95rem" fontWeight="900" color="white" textTransform="uppercase" whiteSpace="nowrap">{last}</Text>
                <Small fontSize="0.62rem">{r.position}</Small>
                {r.transfer && r.previous_school && <Text fontSize="0.66rem" fontWeight="900" color={palette.ink} whiteSpace="nowrap" lineClamp={1}>via {r.previous_school}</Text>}
              </Flex>
              <Box h="0.5rem" mt="0.25rem" bg="rgba(255,255,255,0.05)" borderRadius="2px" overflow="hidden">
                <Box h="100%" bg={palette.ink} style={{ width: `${(r.par / max) * 100}%` }} />
              </Box>
            </Box>
            <Text w="3rem" textAlign="right" fontSize="1.05rem" fontWeight="950" color="white" fontVariantNumeric="tabular-nums">{n1(r.par)}</Text>
          </Flex>
        );
      })}
    </Flex>
  );
};

// ── 9 · Home, away, neutral ──────────────────────────────────────────────────
export const HomeAwayChart = ({ chart, palette, mobile }) => {
  const d = chart.data ?? {};
  const tiles = [["home", "Home"], ["away", "Away"], ["neutral", "Neutral"]].filter(([k]) => d[k]);
  return (
    <Grid templateColumns={`repeat(${tiles.length}, minmax(0,1fr))`} gap="0.5rem">
      {tiles.map(([k, label]) => {
        const t = d[k];
        const [w, l] = String(t.record).split("-").map(Number);
        return (
          <Flex key={k} direction="column" gap="0.3rem" bg="rgba(255,255,255,0.04)" borderRadius="md" p="0.7rem" minW={0} borderTop={`3px solid ${w > l ? palette.ink : w < l ? RED : GREY}`}>
            <Small>{label}</Small>
            <Text fontSize={mobile ? "1.8rem" : "2.2rem"} fontWeight="950" fontStyle="italic" color="white" lineHeight={1}>{t.record}</Text>
            <Text fontSize="0.8rem" fontWeight="800" color="rgba(255,255,255,0.8)">{t.points_for}-{t.points_against} · {signed1(t.avg_margin)}/g</Text>
            {t.avg_attendance != null && <Small fontSize="0.6rem">{Number(t.avg_attendance).toLocaleString()} avg crowd</Small>}
            {(t.events ?? []).length > 0 && <Text fontSize="0.66rem" fontWeight="700" color={FAINT} lineHeight={1.3}>{t.events.join(" · ")}</Text>}
          </Flex>
        );
      })}
    </Grid>
  );
};

// ── 10 · The race: the chance of each finishing place ────────────────────────
export const RaceChart = ({ chart, palette, teamId }) => {
  const d = chart.data ?? {};
  const odds = d.finish_odds_pct ?? [];
  const fav = d.favorite && d.favorite !== teamId ? d.favorite : null;
  return (
    <Box>
      <Flex align="baseline" gap="0.6rem" wrap="wrap">
        <Text fontSize="2.6rem" fontWeight="950" fontStyle="italic" color="white" lineHeight={1}>{pct0(d.title_odds_pct)}</Text>
        <Text fontSize="0.95rem" fontWeight="900" color="rgba(255,255,255,0.8)" textTransform="uppercase">to win the {String(d.group ?? "").replace(/^(SWAC|MEAC)\s+/i, "") || "division"}</Text>
        {d.controls_destiny && <Small color={palette.ink}>Controls its own destiny</Small>}
      </Flex>
      <Flex h="2rem" mt="0.8rem" borderRadius="4px" overflow="hidden">
        {odds.map((v, i) => (
          <Flex key={i} align="center" justify="center" bg={palette.ink} style={{ width: `${v}%`, opacity: 1 - i * (0.75 / Math.max(1, odds.length - 1)) }} borderRight="1px solid #141416">
            {v >= 9 && <Text fontSize="0.72rem" fontWeight="950" color="white">{ordinal(i + 1)}</Text>}
          </Flex>
        ))}
      </Flex>
      <Flex mt="0.3rem">
        {odds.map((v, i) => (
          <Box key={i} style={{ width: `${v}%` }} textAlign="center" minW={0}>
            {v >= 9 && <Text fontSize="0.66rem" fontWeight="900" color={MUTED}>{pct0(v)}</Text>}
          </Box>
        ))}
      </Flex>
      {fav && (
        <Flex align="center" gap="0.5rem" mt="0.9rem" pt="0.7rem" borderTop={`1px solid ${LINE}`}>
          <Image src={TEAM_BY_V5[fav]?.logo} alt="" w="1.6rem" h="1.6rem" objectFit="contain" />
          <Text fontSize="0.85rem" fontWeight="900" color="white" textTransform="uppercase">{shortOf(fav)}</Text>
          <Text fontSize="0.85rem" fontWeight="800" color={MUTED}>favored at {pct0(d.favorite_odds_pct)}</Text>
        </Flex>
      )}
    </Box>
  );
};
