import { Box, Flex, Grid, Spinner, Text } from "@chakra-ui/react";
import PageShell from "../../components/layouts/PageShell";
import { useLayoutDensity } from "../../hooks/useLayoutDensity";
import { useTeamSpotlight } from "../../hooks/useTeamSpotlight";
import { SpotCard } from "../../components/organisms/spotlight/SpotCard";
import { SpotlightBanner, SpotlightBannerMobile } from "../../components/organisms/spotlight/SpotlightBanner";
import { chartOf, paletteOf } from "../../components/organisms/spotlight/spotlightModel";
import {
  CarriesChart, ClimbChart, FieldPositionChart, FingerprintChart, HomeAwayChart,
  PossessionsChart, QuartersChart, RaceChart, SwingsChart, WinProbChart,
} from "../../components/organisms/spotlight/SpotCharts";

// ─────────────────────────────────────────────────────────────────────────────
// TEAM SPOTLIGHT — /schools/spotlight (Schools hub). The week's Team of the
// Week, as a full season profile painted in that team's colours, like the
// school pages. Ten cards, each its own exportable image, in the order the
// season reads: the climb and the race, every game's win probability, what
// they are, every possession, when they win it, field position, who carries
// it, the swing plays, home and away.
//
// Desktop: PageShell, the banner as the 4x1, the cards as the scrolling list
// under it. Mobile: its own tree, no PageShell — banner, then the cards flush.
// Data: useTeamSpotlight (a copy of the backend's weekly file until it's
// published; see the hook).
// ─────────────────────────────────────────────────────────────────────────────

// [chart id, card component, desktop span (1 = half, 2 = full)]
const CARDS = [
  ["rating_climb", ClimbChart, 1],
  ["division_odds", RaceChart, 1],
  ["season_in_win_probability", WinProbChart, 2],
  ["fingerprint", FingerprintChart, 2],
  ["every_possession", PossessionsChart, 2],
  ["quarter_by_quarter", QuartersChart, 1],
  ["field_position", FieldPositionChart, 1],
  ["who_carries_it", CarriesChart, 1],
  ["swing_plays", SwingsChart, 1],
  ["home_and_away", HomeAwayChart, 2],
];

const Cards = ({ spotlight, palette, mobile }) => {
  const teamId = spotlight.team_id;
  const stamp = `${spotlight.season}-w${spotlight.through_week}-${teamId}`;
  const cards = CARDS.map(([id, Chart, span]) => {
    const chart = chartOf(spotlight, id);
    if (!chart) return null;
    return (
      <Box key={id} gridColumn={!mobile && span === 2 ? "1 / -1" : undefined} minW={0}>
        <SpotCard title={chart.title} palette={palette} mobile={mobile} filename={`spotlight-${stamp}-${id}.png`.replace(/_/g, "-")}>
          <Chart chart={chart} palette={palette} teamId={teamId} mobile={mobile} />
        </SpotCard>
      </Box>
    );
  });
  return mobile
    ? <Flex direction="column">{cards}</Flex>
    : <Grid templateColumns="repeat(2, minmax(0, 1fr))" gap={4} alignItems="start">{cards}</Grid>;
};

const TeamSpotlightPage = () => {
  const { spotlight, isLoading, isError } = useTeamSpotlight();
  const { isMobile } = useLayoutDensity();
  const palette = paletteOf(spotlight?.team_id);

  const status = isLoading ? (
    <Flex justify="center" py={20}><Spinner color="brand.500" size="lg" /></Flex>
  ) : isError || !spotlight ? (
    <Flex justify="center" py={20}><Text color="text.muted">No Team Spotlight this week yet.</Text></Flex>
  ) : null;

  if (isMobile) {
    return (
      <Box minH="100vh" bg="bg.primary" pt="var(--app-header-height)">
        {spotlight && <SpotlightBannerMobile spotlight={spotlight} palette={palette} />}
        {status ?? <Cards spotlight={spotlight} palette={palette} mobile />}
      </Box>
    );
  }

  return (
    <PageShell listContent={status ?? <Cards spotlight={spotlight} palette={palette} />}>
      <PageShell.Slot cols={4}>
        {spotlight ? <SpotlightBanner spotlight={spotlight} palette={palette} /> : <Box />}
      </PageShell.Slot>
    </PageShell>
  );
};

export default TeamSpotlightPage;
